import type { CarClass, CarClassId, Tuning } from '@sim'
import { newbie } from './newbie'

export { newbie }

/** Some of the values of a group, nested as in the group itself: what a preset changes and nothing else. */
export type Changes<T> = { [K in keyof T]?: T[K] extends object ? Changes<T[K]> : T[K] }

/** What a preset may change in a class row: its numbers, never what names the class or how it is driven. */
export type ClassChanges = Changes<Omit<CarClass, 'id' | 'name' | 'character' | 'drive'>>

/**
 * A preset shipped with the game (F-807): the tuning panel lists it before the player's own, applies it like one of
 * theirs, and never writes it to storage, deletes it or saves over it. It is the same changes an export holds, as
 * data: one set for the tuning block, which every class shares, and one for each class row. Loading it puts the
 * whole set in place, so the class the player changes to next has it too.
 */
export interface ShippedPreset {
  /** What the panel lists it as; no preset of the player's may take it. */
  name: string
  /** One line for the panel and the guide. */
  about: string
  tuning: Changes<Tuning>
  classes: Readonly<Record<CarClassId, ClassChanges>>
}

/** The shipped presets, in the order the panel lists them, before the player's own. */
export const SHIPPED_PRESETS: readonly ShippedPreset[] = [newbie]
