import type { CarClass, CarClassId, Tuning } from '@sim'
import { conform, isLeaf, isObject, presetClass, presetTuning, type Leaf, type PresetData } from '../race/presets'

export type { Leaf, PresetData }

// Everything the tuning panel does with numbers that needs no browser, no Phaser and no Tweakpane (F-206): reading
// a class row or the tuning block as a list of dotted paths, the slider range of each, the difference from the
// shipped values, and the text form that goes to the clipboard and comes back. The panel is a thin shell over this.

/** A class row or the tuning block: the two things the panel edits. */
export type Tunable = CarClass | Tuning

/** One value that differs from the shipped one, by dotted path (`motor.kv`, `shaping.steerRatePerS`). */
export interface Change {
  path: string
  from: Leaf
  to: Leaf
}

/** The slider range of one number. */
export interface Range {
  min: number
  max: number
  step: number
}

/** Every class row, by id: what the panel works on and what the shipped content holds. */
export type ClassTable = Readonly<Record<CarClassId, CarClass>>

// ---------------------------------------------------------------------------------------------------------------
// Walking a value by dotted path
// ---------------------------------------------------------------------------------------------------------------

/** A typed object seen as the record it is. The one place the panel's generic walking leans on a cast. */
function asRecord(value: object): Record<string, unknown> {
  return value as Record<string, unknown>
}

/** Every value of `value`, as dotted paths in the order the object declares them. Numbers, strings and booleans are leaves. */
export function leafPaths(value: object, prefix = ''): string[] {
  const paths: string[] = []
  for (const [key, child] of Object.entries(asRecord(value))) {
    const path = prefix === '' ? key : `${prefix}.${key}`
    if (isLeaf(child)) paths.push(path)
    else if (isObject(child)) paths.push(...leafPaths(child, path))
    else throw new TypeError(`'${path}' is neither a value nor a group of values`)
  }
  return paths
}

/** The value at a dotted path, or undefined if the path leads nowhere or ends on a group. */
export function leafAt(value: object, path: string): Leaf | undefined {
  let here: unknown = value
  for (const key of path.split('.')) {
    if (!isObject(here)) return undefined
    here = here[key]
  }
  return isLeaf(here) ? here : undefined
}

/** The object that holds the last key of a dotted path, and that key; the path must exist. */
export function holderOf(value: object, path: string): { holder: Record<string, unknown>; key: string } {
  const keys = path.split('.')
  const key = keys[keys.length - 1]
  let holder = asRecord(value)
  for (const step of keys.slice(0, -1)) {
    const next = holder[step]
    if (!isObject(next)) throw new RangeError(`No group '${step}' on the way to '${path}'`)
    holder = next
  }
  return { holder, key }
}

/** Sets the value at a dotted path to one of the same kind. */
export function setLeaf(value: object, path: string, to: Leaf): void {
  const { holder, key } = holderOf(value, path)
  const was = holder[key]
  if (!isLeaf(was)) throw new RangeError(`'${path}' is not a value`)
  if (typeof was !== typeof to) throw new TypeError(`'${path}' is ${typeof was}, not ${typeof to}`)
  holder[key] = to
}

/** Writes every value of `from` into the same place in `into`, which must have the same fields; `into` keeps its identity. */
export function copyLeaves(into: object, from: object): void {
  for (const path of leafPaths(from)) {
    const value = leafAt(from, path)
    if (value === undefined) throw new RangeError(`copyLeaves: '${path}' vanished`)
    setLeaf(into, path, value)
  }
}

/** A copy that shares nothing with the original. */
export function cloneValue<T extends Tunable>(value: T): T {
  return structuredClone(value)
}

/**
 * Fields of a class row that stay in the row (and in the class files) but are not the panel's to edit (F-812): the
 * pit stops a final owes are read from the shipped class file when a session is built, so a row for them did nothing.
 * They get no control and no range, are never written to an export, and an import or a preset that holds one leaves it as shipped.
 */
export const NOT_IN_PANEL: readonly string[] = ['mandatoryPitStops']

/** The paths the panel shows a control for: every value but the ones in `NOT_IN_PANEL`. */
export function panelPaths(value: object): string[] {
  return leafPaths(value).filter((path) => !NOT_IN_PANEL.includes(path))
}

/** The paths of the numbers only (the sliders). */
export function numericPaths(value: object): string[] {
  return panelPaths(value).filter((path) => typeof leafAt(value, path) === 'number')
}

/** A class row read from outside (an import, a preset) with the fields that are not the panel's put back to the shipped row's. */
function withShippedUntuned(row: CarClass, shipped: CarClass): CarClass {
  const out = cloneValue(row)
  for (const path of NOT_IN_PANEL) {
    const value = leafAt(shipped, path)
    if (value !== undefined) setLeaf(out, path, value)
  }
  return out
}

// ---------------------------------------------------------------------------------------------------------------
// Difference from the shipped values
// ---------------------------------------------------------------------------------------------------------------

/**
 * Every value of `tuned` that differs from `base`, with both. The two must have the same shape: a value that one
 * has and the other lacks is a mistake, not a difference.
 */
export function diffValues<T extends Tunable>(base: T, tuned: T): Change[] {
  const basePaths = leafPaths(base)
  const tunedPaths = leafPaths(tuned)
  if (basePaths.length !== tunedPaths.length || basePaths.some((path, i) => path !== tunedPaths[i])) {
    throw new TypeError('diffValues: the two values do not have the same fields')
  }
  const changes: Change[] = []
  for (const path of basePaths) {
    const from = leafAt(base, path)
    const to = leafAt(tuned, path)
    if (from === undefined || to === undefined) throw new RangeError(`diffValues: '${path}' vanished`)
    if (from !== to) changes.push({ path, from, to })
  }
  return changes
}

/** The same changes with a group name in front of every path (`tuning.currentLimitA`, `class.cgHeightM`). */
export function withPrefix(prefix: string, changes: readonly Change[]): Change[] {
  return changes.map((change) => ({ ...change, path: `${prefix}.${change.path}` }))
}

function showLeaf(value: Leaf): string {
  return typeof value === 'string' ? `'${value}'` : String(value)
}

/** The changes as lines for pasting into feedback: a heading with the label and the count, then `path: old → new`. */
export function formatDiff(label: string, diff: readonly Change[]): string {
  if (diff.length === 0) return `${label}: no changes from the shipped values`
  const lines = diff.map((change) => `  ${change.path}: ${showLeaf(change.from)} → ${showLeaf(change.to)}`)
  return [`${label}: ${diff.length} ${diff.length === 1 ? 'change' : 'changes'}`, ...lines].join('\n')
}

