/** The step a slider over a number of this size gets when nothing says otherwise: a hundredth of its size, to two significant figures. */
function fallbackStep(size: number): number {
  const raw = Math.max(size, 1e-6) / 100
  const magnitude = 10 ** Math.floor(Math.log10(raw))
  return magnitude * Math.max(1, Math.round(raw / magnitude))
}

/** True when `RANGES` has an entry for the path; false when `rangeFor` would have to make one up. */
export function hasRange(path: string): boolean {
  return Object.hasOwn(RANGES, path)
}

/**
 * The slider range of a number: the table's, stretched if need be to hold the current value (so a shipped value is
 * never off its slider), or, for a number the table does not know, one made from the value itself: zero to twice
 * its size (or symmetric if it is negative), at a hundredth of that.
 */
export function rangeFor(path: string, current: number): Range {
  const known = Object.hasOwn(RANGES, path) ? RANGES[path] : null
  if (known !== null) {
    const min = Math.min(known.min, current)
    const max = Math.max(known.max, current)
    return { min, max, step: known.step }
  }
  const size = Math.abs(current) === 0 ? 1 : Math.abs(current) * 2
  return { min: current < 0 ? -size : 0, max: size, step: fallbackStep(size) }
}

/** The unit a number's name ends in, for the label beside its slider; '' when the name says nothing. */
export function unitOf(path: string): string {
  const name = path.slice(path.lastIndexOf('.') + 1)
  const endings: Array<[RegExp, string]> = [
    [/PerS$/, '/s'],
    [/PerKg$/, 'N/kg'],
    [/PerM$/, '/m'],
    [/RadS$/, 'rad/s'],
    [/Rad$/, 'rad'],
    [/MS$/, 'm/s'],
    [/NPer/, ''],
    [/KgM2$/, 'kg·m²'],
    [/Kg$/, 'kg'],
    [/M$/, 'm'],
    [/S$/, 's'],
    [/A$/, 'A'],
    [/W$/, 'W'],
  ]
  for (const [pattern, unit] of endings) if (pattern.test(name)) return unit
  return ''
}

// ---------------------------------------------------------------------------------------------------------------
// Reading a TypeScript object literal
// ---------------------------------------------------------------------------------------------------------------

/**
 * A reader for the one kind of text this feature exchanges: an object literal of numbers, strings and booleans,
 * with comments and trailing commas, where a number may be a small sum, product or quotient (`(28 * Math.PI) / 180`,
 * the way the content files write angles). It is not an evaluator: nothing else is accepted.
 */
class Reader {
  private pos = 0

  constructor(private readonly src: string) {}

  fail(message: string): never {
    const upTo = this.src.slice(0, this.pos)
    const line = upTo.split('\n').length
    const column = this.pos - (upTo.lastIndexOf('\n') + 1) + 1
    throw new SyntaxError(`${message} (line ${line}, column ${column})`)
  }

  private skip(): void {
    for (;;) {
      const here = this.src[this.pos]
      if (here === ' ' || here === '\t' || here === '\n' || here === '\r') this.pos++
      else if (this.src.startsWith('//', this.pos)) {
        const end = this.src.indexOf('\n', this.pos)
        this.pos = end < 0 ? this.src.length : end + 1
      } else if (this.src.startsWith('/*', this.pos)) {
        const end = this.src.indexOf('*/', this.pos + 2)
        if (end < 0) this.fail('A comment that never ends')
        this.pos = end + 2
      } else return
    }
  }

  private peek(): string {
    this.skip()
    return this.src[this.pos] ?? ''
  }

  private eat(text: string): boolean {
    this.skip()
    if (!this.src.startsWith(text, this.pos)) return false
    this.pos += text.length
    return true
  }

  private expect(text: string): void {
    if (!this.eat(text)) this.fail(`Expected '${text}'`)
  }

  /** The whole text: an optional `export const name: Type =` in front, one value, an optional `;`, nothing more. */
  document(): unknown {
    this.skip()
    const declaration = /^(?:export\s+)?(?:const|let|var)\s+[A-Za-z_$][\w$]*\s*(?::[^=]*)?=/.exec(this.src.slice(this.pos))
    if (declaration !== null) this.pos += declaration[0].length
    const value = this.value()
    this.eat(';')
    this.skip()
    if (this.pos < this.src.length) this.fail('Unexpected text after the value')
    return value
  }

  private value(): unknown {
    const next = this.peek()
    if (next === '{') return this.object()
    if (next === "'" || next === '"') return this.string()
    if (this.src.startsWith('true', this.pos) && !/[\w$]/.test(this.src[this.pos + 4] ?? '')) {
      this.pos += 4
      return true
    }
    if (this.src.startsWith('false', this.pos) && !/[\w$]/.test(this.src[this.pos + 5] ?? '')) {
      this.pos += 5
      return false
    }
    return this.sum()
  }

  private object(): Record<string, unknown> {
    this.expect('{')
    const out: Record<string, unknown> = {}
    while (this.peek() !== '}') {
      const key = this.key()
      if (Object.hasOwn(out, key)) this.fail(`'${key}' appears twice`)
      this.expect(':')
      out[key] = this.value()
      if (!this.eat(',') && this.peek() !== '}') this.fail("Expected ',' or '}'")
    }
    this.expect('}')
    return out
  }

  private key(): string {
    const next = this.peek()
    if (next === "'" || next === '"') return this.string()
    const word = /^[A-Za-z_$][\w$]*/.exec(this.src.slice(this.pos))
    if (word === null) this.fail('Expected a field name')
    this.pos += word[0].length
    return word[0]
  }

  private string(): string {
    const quote = this.src[this.pos]
    this.pos++
    let out = ''
    for (;;) {
      const here = this.src[this.pos]
      if (here === undefined || here === '\n') this.fail('A string that never ends')
      this.pos++
      if (here === quote) return out
      if (here !== '\\') {
        out += here
        continue
      }
      const escaped = this.src[this.pos]
      this.pos++
      if (escaped === 'n') out += '\n'
      else if (escaped === 't') out += '\t'
      else if (escaped === undefined) this.fail('A string that never ends')
      else out += escaped
    }
  }

  private sum(): number {
    let total = this.product()
    for (;;) {
      if (this.eat('+')) total += this.product()
      else if (this.eat('-')) total -= this.product()
      else return total
    }
  }

  private product(): number {
    let total = this.unary()
    for (;;) {
      if (this.eat('*')) total *= this.unary()
      else if (this.eat('/')) total /= this.unary()
      else return total
    }
  }

  private unary(): number {
    if (this.eat('-')) return -this.unary()
    if (this.eat('+')) return this.unary()
    return this.atom()
  }

  private atom(): number {
    if (this.eat('(')) {
      const inner = this.sum()
      this.expect(')')
      return inner
    }
    if (this.eat('Math.PI')) return Math.PI
    this.skip()
    const literal = /^(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?/.exec(this.src.slice(this.pos))
    if (literal === null) this.fail('Expected a number, a string, true, false or {')
    this.pos += literal[0].length
    return Number(literal[0])
  }
}

/** The value a piece of text holds: nested records, numbers, strings and booleans. */
export function parseLiteral(src: string): unknown {
  return new Reader(src).document()
}

/**
 * Reads text back into a value of the same shape as `shape` (a shipped class row or the tuning block): every field
 * present, no field the shape lacks, every value of the shape's kind.
 */
export function fromCode<T extends Tunable>(src: string, shape: T): T {
  return conform(parseLiteral(src), shape, '', false) as T
}

// ---------------------------------------------------------------------------------------------------------------
// Writing a TypeScript object literal
// ---------------------------------------------------------------------------------------------------------------

function literalOf(value: Leaf): string {
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) throw new RangeError(`${value} cannot be written as a number literal`)
    return Object.is(value, -0) ? '0' : String(value)
  }
  if (typeof value === 'boolean') return String(value)
  return `'${value.replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\n/g, '\\n')}'`
}

const KEY_PATTERN = /^[A-Za-z_$][\w$]*$/

function keyOf(key: string): string {
  return KEY_PATTERN.test(key) ? key : literalOf(key)
}

/** A group whose members are all plain values and which fits on one line is written on one line, as the content files do. */
const INLINE_WIDTH = 100

function writeGroup(group: Record<string, unknown>, indent: string, notes: ((path: string) => string) | null, path: string): string {
  const entries = Object.entries(group)
  const inline = entries.map(([key, child]) => (isLeaf(child) ? `${keyOf(key)}: ${literalOf(child)}` : null))
  if (notes === null && indent !== '' && inline.every((part) => part !== null)) {
    const line = `{ ${inline.join(', ')} }`
    if (line.length + indent.length <= INLINE_WIDTH) return line
  }
  const inner = `${indent}  `
  const lines = entries.map(([key, child]) => {
    const childPath = path === '' ? key : `${path}.${key}`
    if (isLeaf(child)) {
      const note = notes === null ? '' : notes(childPath)
      return `${inner}${keyOf(key)}: ${literalOf(child)},${note === '' ? '' : ` // ${note}`}`
    }
    if (!isObject(child)) throw new TypeError(`'${childPath}' is neither a value nor a group of values`)
    return `${inner}${keyOf(key)}: ${writeGroup(child, inner, notes, childPath)},`
  })
  return `{\n${lines.join('\n')}\n${indent}}`
}

/** The value as a TypeScript object literal, the way a content file writes it, to paste over the object in that file. */
export function toCode(value: Tunable): string {
  return writeGroup(asRecord(value), '', null, '')
}

// ---------------------------------------------------------------------------------------------------------------
// The workspace, and the export that shows only what differs
// ---------------------------------------------------------------------------------------------------------------

/**
 * The shipped values and the working copies the panel edits. The shipped objects themselves are never written to,
 * and the working objects are never replaced, only written into, so that the panel's sliders stay bound to them.
 */
export interface Workspace {
  readonly shippedTuning: Tuning
  readonly shippedClasses: ClassTable
  readonly tuning: Tuning
  readonly classes: Readonly<Record<CarClassId, CarClass>>
}

/** A workspace whose working copies are deep copies of what is shipped. */
export function createWorkspace(shippedTuning: Tuning, shippedClasses: ClassTable): Workspace {
  return {
    shippedTuning,
    shippedClasses,
    tuning: cloneValue(shippedTuning),
    classes: {
      'tc-stock-175': cloneValue(shippedClasses['tc-stock-175']),
      'tc-mod-45': cloneValue(shippedClasses['tc-mod-45']),
      'fwd-105': cloneValue(shippedClasses['fwd-105']),
      'f1-215': cloneValue(shippedClasses['f1-215']),
    },
  }
}

/** Everything that differs from the shipped values for one class: `tuning.…` paths first, then `class.…`. */
export function workspaceChanges(ws: Workspace, id: CarClassId): Change[] {
  return [
    ...withPrefix('tuning', diffValues(ws.shippedTuning, ws.tuning)),
    ...withPrefix('class', diffValues(ws.shippedClasses[id], ws.classes[id])),
  ]
}

/** The same, for every class at once: what has been edited anywhere in the workspace. */
export function workspaceAltered(ws: Workspace): boolean {
  if (diffValues(ws.shippedTuning, ws.tuning).length > 0) return true
  return (Object.keys(ws.classes) as CarClassId[]).some((id) => diffValues(ws.shippedClasses[id], ws.classes[id]).length > 0)
}

/** Puts every working value back to the shipped one, exactly. */
export function resetWorkspace(ws: Workspace): void {
  copyLeaves(ws.tuning, ws.shippedTuning)
  for (const id of Object.keys(ws.classes) as CarClassId[]) copyLeaves(ws.classes[id], ws.shippedClasses[id])
}

/** Writes an edited copy of a class row over its working row (the row's id decides which). */
export function putClass(ws: Workspace, row: CarClass): void {
  copyLeaves(ws.classes[row.id], row)
}

/** Only the changed values of a group, nested as in the group itself, for the export. */
function onlyChanged(changes: readonly Change[], prefix: string): Record<string, unknown> {
  const out: Record<string, unknown> = {}
  for (const change of changes) {
    if (!change.path.startsWith(`${prefix}.`)) continue
    const path = change.path.slice(prefix.length + 1)
    const keys = path.split('.')
    let into = out
    for (const step of keys.slice(0, -1)) {
      const next = into[step]
      if (isObject(next)) into = next
      else {
        const fresh: Record<string, unknown> = {}
        into[step] = fresh
        into = fresh
      }
    }
    into[keys[keys.length - 1]] = change.to
  }
  return out
}

/**
 * The export: a TypeScript object literal with the values that differ from the shipped ones and nothing else, each
 * with the shipped value in a comment, headed by the files to paste it into. `tuning` holds the changes to the
 * tuning block, `class` the changes to one class row, named by its `id`. It reads back with `fromPatchText`.
 */
export function toPatchText(ws: Workspace, id: CarClassId): string {
  const changes = workspaceChanges(ws, id)
  const was = new Map(changes.map((change) => [change.path, change.from]))
  const tuningPart = onlyChanged(changes, 'tuning')
  const classPart = { id, ...onlyChanged(changes, 'class') }
  const body: Record<string, unknown> = {}
  if (Object.keys(tuningPart).length > 0) body.tuning = tuningPart
  if (Object.keys(classPart).length > 1) body.class = classPart
  const head = [
    `// Mini RC Racers tuning, class ${id}: only what differs from the shipped values; "was" is the shipped value.`,
    `// Paste the tuning values into src/content/tuning.ts and the class values into src/content/classes/${id}.ts`,
  ]
  if (Object.keys(body).length === 0) return [...head, '// (nothing differs)', '{}'].join('\n')
  const note = (path: string): string => {
    const from = was.get(path)
    return from === undefined ? '' : `was ${literalOf(from)}`
  }
  return [...head, writeGroup(body, '', note, '')].join('\n')
}

/** What `fromPatchText` found: the tuning block if the text had changes to it, and one class row if the text had changes to one. */
export interface Imported {
  tuning: Tuning | null
  car: CarClass | null
  /**
   * True for the text `toPatchText` writes, which describes the whole state against the shipped values: a part it
   * leaves out is the shipped one. False for a bare class row or tuning block, which says nothing about the other.
   */
  complete: boolean
}

/**
 * Reads what `toPatchText` wrote — or a whole class row or tuning block as `toCode` or a content file writes
 * it — onto the shipped values: whatever the text leaves out is the shipped value, so the result is exactly what
 * was exported. Throws with a reason (and a line, for a syntax error) on text it cannot use.
 */
export function fromPatchText(src: string, shippedTuning: Tuning, shippedClasses: ClassTable): Imported {
  const parsed = parseLiteral(src)
  if (!isObject(parsed)) throw new TypeError('Expected an object literal')
  const keys = Object.keys(parsed)
  const wrapped = keys.length > 0 && keys.every((key) => key === 'tuning' || key === 'class')
  if (keys.length === 0) return { tuning: null, car: null, complete: true }
  if (wrapped) {
    const tuningPart = parsed.tuning
    const classPart = parsed.class
    const tuning = tuningPart === undefined ? null : (conform(tuningPart, shippedTuning, 'tuning', true) as Tuning)
    return { tuning, car: classPart === undefined ? null : classFromLiteral(classPart, shippedClasses, 'class'), complete: true }
  }
  if (Object.hasOwn(parsed, 'id')) return { tuning: null, car: classFromLiteral(parsed, shippedClasses, ''), complete: false }
  return { tuning: conform(parsed, shippedTuning, '', true) as Tuning, car: null, complete: false }
}

function classFromLiteral(parsed: unknown, shippedClasses: ClassTable, path: string): CarClass {
  const id = isObject(parsed) ? parsed.id : undefined
  if (typeof id !== 'string' || !Object.hasOwn(shippedClasses, id)) throw new TypeError(`${path === '' ? 'The class row' : `'${path}'`} needs an id naming a class`)
  const shipped = shippedClasses[id as CarClassId]
  return withShippedUntuned(conform(parsed, shipped, path, true) as CarClass, shipped)
}

// ---------------------------------------------------------------------------------------------------------------
// Presets shipped with the game (F-807)
// ---------------------------------------------------------------------------------------------------------------

/**
 * Puts a shipped preset in place: every working value back to the shipped one, then the preset's changes to the
 * tuning block and to every class row it names, so that each class has it. The preset is checked whole before
 * anything is written: a field the shipped values lack, or a value of the wrong kind, throws and changes nothing.
 */
export function applyPreset(ws: Workspace, preset: PresetData): void {
  // The changes are put over the shipped values by the same code that gives the player's car DRIVING ASSISTANCE (F-811).
  const tuned = presetTuning(preset, ws.shippedTuning)
  const rows = (Object.keys(preset.classes) as CarClassId[]).map((id) => {
    if (!Object.hasOwn(ws.shippedClasses, id)) throw new TypeError(`'${id}' is not a class`)
    return withShippedUntuned(presetClass(preset, ws.shippedClasses[id]), ws.shippedClasses[id])
  })
  resetWorkspace(ws)
  copyLeaves(ws.tuning, tuned)
  for (const row of rows) putClass(ws, row)
}

/** One entry of the panel's list of presets. `key` is what the list selects, and never the same for two entries. */
export interface PresetChoice {
  key: string
  label: string
  shipped: boolean
}

const SHIPPED_KEY = 'shipped:'
const SAVED_KEY = 'saved:'

/** The panel's list: the shipped presets first, in their own order and marked as shipped, then the player's own by name. */
export function presetChoices(shipped: readonly PresetData[], saved: Readonly<Record<string, string>>): PresetChoice[] {
  return [
    ...shipped.map((preset) => ({ key: `${SHIPPED_KEY}${preset.name}`, label: `${preset.name} (shipped)`, shipped: true })),
    ...Object.keys(saved)
      .sort()
      .map((name) => ({ key: savedPresetKey(name), label: name, shipped: false })),
  ]
}

/** The shipped preset a list key selects, or null when it selects one of the player's own. */
export function shippedPresetOf<T extends PresetData>(shipped: readonly T[], key: string): T | null {
  if (!key.startsWith(SHIPPED_KEY)) return null
  return shipped.find((preset) => `${SHIPPED_KEY}${preset.name}` === key) ?? null
}

/** The list key of the player's own preset of this name. */
export function savedPresetKey(name: string): string {
  return `${SAVED_KEY}${name}`
}

/** The name of the player's own preset a list key selects, or null when it selects a shipped one. */
export function savedPresetName(key: string): string | null {
  return key.startsWith(SAVED_KEY) ? key.slice(SAVED_KEY.length) : null
}

/** True when a name is a shipped preset's, whatever its case or the spaces round it: a player's preset may not take it. */
export function isShippedPresetName(shipped: readonly PresetData[], name: string): boolean {
  const wanted = name.trim().toLowerCase()
  return shipped.some((preset) => preset.name.toLowerCase() === wanted)
}
