import type { CarSnapshot } from '@sim'

// What the car is doing, as the numbers the tuning panel shows (F-206). Pure: it reads a snapshot and writes a flat
// object of plain numbers, which the panel's readouts and graphs poll. No DOM and no Tweakpane here.

/** Standard gravity, m/s². Lateral g is measured against it, whatever the game's grip scale is. */
export const STANDARD_G_MS2 = 9.81

const RAD_S_TO_RPM = 60 / (2 * Math.PI)
const RAD_TO_DEG = 180 / Math.PI

/** Lateral acceleration of a car on a steady curve in g: speed × yaw rate / g. Positive when turning right (yaw is clockwise). */
export function lateralG(speedMS: number, yawRateRadS: number): number {
  return (speedMS * yawRateRadS) / STANDARD_G_MS2
}

/** The readouts, every one a plain number so that a monitor can poll the object. */
export interface TelemetryValues {
  /** Signed along the heading, m/s. */
  speedMS: number
  /** Motor shaft speed, rpm. */
  motorRpm: number
  /** After the input shaping, 0..1. */
  throttle: number
  brake: number
  /** Road-wheel angle, degrees, positive to the right. */
  steerDeg: number
  /** Speed × yaw rate / g. */
  lateralG: number
  /** Yaw rate, degrees per second, positive to the right. */
  yawRateDegS: number
  /** Saturation of each axle's grip, 0..1+: at 1 the tyres are at their limit. */
  slipFront: number
  slipRear: number
}

export function blankTelemetry(): TelemetryValues {
  return { speedMS: 0, motorRpm: 0, throttle: 0, brake: 0, steerDeg: 0, lateralG: 0, yawRateDegS: 0, slipFront: 0, slipRear: 0 }
}

/** Writes the car's readouts into `into` (the same object every frame, so that nothing is allocated). */
export function readTelemetry(car: CarSnapshot | null, into: TelemetryValues): void {
  if (car === null) {
    Object.assign(into, blankTelemetry())
    return
  }
  into.speedMS = car.speedMS
  into.motorRpm = car.motorRadS * RAD_S_TO_RPM
  into.throttle = car.throttle
  into.brake = car.brake
  into.steerDeg = car.steerRad * RAD_TO_DEG
  into.lateralG = lateralG(car.speedMS, car.yawRateRadS)
  into.yawRateDegS = car.yawRateRadS * RAD_TO_DEG
  into.slipFront = car.slipFront
  into.slipRear = car.slipRear
}

/** The monitors poll at this interval, which is also how often the graphs take a sample: 20 Hz. */
export const GRAPH_INTERVAL_MS = 50

/** What each graph shows: its label, the readout it follows and the range its axis covers. */
export const GRAPHS: ReadonlyArray<{ key: keyof TelemetryValues; label: string; min: number; max: number }> = [
  { key: 'speedMS', label: 'speed m/s', min: -2, max: 8 },
  { key: 'lateralG', label: 'lateral g', min: -1, max: 1 },
  { key: 'slipFront', label: 'front slip', min: 0, max: 1.5 },
  { key: 'slipRear', label: 'rear slip', min: 0, max: 1.5 },
]
