// The tuning panel (F-206): Tweakpane, over the pure parts in tuning-io.ts. It is loaded by a dynamic import from main.ts: at
// start in development, test and demo builds, and in the released game only once the player has typed the code (F-813). It is a
// chunk of its own, and nothing that production loads at start imports it.
//
// How a changed value reaches the car: the panel keeps working copies of the tuning block and of every class row
// (the shipped objects are never written to), resolves the running car's class and tuning into `CarParams` with the
// sim's own `resolveCar`, and hands them to the session with `setCarParams`. The car keeps its place and speed.

// ---------------------------------------------------------------------------------------------------------------
// The part of Tweakpane's API this file uses. Tweakpane's own typings lean on `@tweakpane/core`, which is not
// installed here, so the compiler sees a `Pane` with no members; this is the shape of the real one, narrowed.
// ---------------------------------------------------------------------------------------------------------------

interface BindingOptions {
  label?: string
  min?: number
  max?: number
  step?: number
  readonly?: boolean
  view?: string
  interval?: number
  bufferSize?: number
  rows?: number
  options?: Record<string, string>
}

interface ChangeEvent {
  value: Leaf
}

interface BindingApi {
  readonly element: HTMLElement
  on(name: 'change', handler: (event: ChangeEvent) => void): BindingApi
  refresh(): void
}

interface ButtonApi {
  on(name: 'click', handler: () => void): ButtonApi
}

interface FolderApi extends Container {
  expanded: boolean
}

interface Container {
  addBinding(target: object, key: string, options?: BindingOptions): BindingApi
  addButton(config: { title: string; label?: string }): ButtonApi
  addFolder(config: { title: string; expanded?: boolean }): FolderApi
  refresh(): void
}

interface PaneApi extends Container {
  hidden: boolean
  disabled: boolean
  dispose(): void
}

function createPane(mount: HTMLElement): PaneApi {
  return new Pane({ container: mount, title: 'Tuning  (T closes)' }) as unknown as PaneApi
}

// ---------------------------------------------------------------------------------------------------------------
// What the panel needs of the game
// ---------------------------------------------------------------------------------------------------------------

/** What the panel needs of the game, given by `installTuningTools`. */
export interface PanelHost {
  /** The session that is running and the latest snapshot of its player's car; null between sessions. */
  current(): { session: Session; car: CarSnapshot } | null
  /** Starts a fresh practice session in this class, replacing the running one. */
  restart(carClass: CarClassId): void
  /** Lets go of every driving key, so that a key held when focus moved to the panel does not stay held. */
  releaseKeys(): void
}

/** What the hook reports of the panel. */
export interface TuningPanelState {
  open: boolean
  carClass: CarClassId
  /** Every value that differs from the shipped one, for the class on the track: `tuning.…` and `class.…` paths. */
  changes: Change[]
  /** The shipped tuning block and class rows still hold exactly what they held when the panel was made. */
  shippedIntact: boolean
  /** The running session has been given altered parameters (and so must not set a lap time that counts). */
  sessionTuned: boolean
  telemetry: TelemetryValues
  /** The line at the top of the panel. */
  status: string
  /** What is in the export / import box. */
  text: string
  /** The preset last loaded, as the list names it (`NEWBIE (shipped)`), while nothing has been edited since; else null. */
  preset: string | null
  /** The working values are the DRIVING ASSISTANCE car's (F-811), put there because the player drives it, and nothing has been changed since. */
  assistance: boolean
}

