// Where each value goes
// ---------------------------------------------------------------------------------------------------------------

/**
 * The levers that matter most to the feel, shown first and outside their own groups: what F-202 found (the current limit and
 * the centre-of-gravity height are the big ones), the two grip numbers, and the two brake numbers it added.
 */
const KEY_LEVERS: ReadonlyArray<{ scope: Scope; path: string; note: string }> = [
  { scope: 'tuning', path: 'currentLimitA', note: 'Pace against push: the Modified’s main lever; barely touches the Stock car above about 84 A' },
  { scope: 'class', path: 'cgHeightM', note: 'The strongest feel lever: lower takes the push out, higher gives tuck-in' },
  { scope: 'class', path: 'muFront', note: 'Front tyre grip: lower it and the car understeers more' },
  { scope: 'class', path: 'muRear', note: 'Rear tyre grip' },
  { scope: 'class', path: 'brakeRearGain', note: 'How hard the brake works the rear axle (1 = the rear reserve as it stands)' },
  { scope: 'class', path: 'brakeSlideGive', note: 'How readily a braked tyre gives up braking for side grip as it slides (0 = never)' },
]

type Scope = 'tuning' | 'class'

const CLASS_FOLDERS: Readonly<Record<string, string>> = {
  massKg: 'Body',
  weightFront: 'Body',
  lengthM: 'Body',
  widthM: 'Body',
  wheelbaseM: 'Body',
  cgHeightM: 'Body',
  yawGyrationM: 'Body',
  drive: 'Drivetrain',
  finalDriveRatio: 'Drivetrain',
  tyreRadiusM: 'Drivetrain',
  motor: 'Motor',
  muFront: 'Tyres',
  muRear: 'Tyres',
  dragArea: 'Air',
  sideArea: 'Air',
  brakeRearGain: 'Brakes',
  brakeSlideGive: 'Brakes',
}

const TUNING_FOLDERS: Readonly<Record<string, string>> = {
  scale: 'Scale',
  tyre: 'Tyre curve',
  slipCancelShare: 'Tyre curve',
  yawSettle: 'Tyre curve',
  currentLimitA: 'Motor and drive',
  packVoltage: 'Motor and drive',
  drivetrainEfficiency: 'Motor and drive',
  beltSplit: 'Motor and drive',
  fourWdStaticFrontShare: 'Motor and drive',
  brakeShare: 'Brakes',
  brakeRearReserve: 'Brakes',
  brakeRearReserveShare: 'Brakes',
  dragBrakeShare: 'Brakes',
  maxSteerRad: 'Steering and resistance',
  rollResistance: 'Steering and resistance',
  reverseLimit: 'Steering and resistance',
  shaping: 'Input shaping',
  contact: 'Contact: walls',
  marker: 'Contact: tyres',
  carContact: 'Contact: cars',
  surface: 'Surface',
}

/**
 * Rows that tell on hover what they are for, by full name (F-812). `motor.turns` is the motor's label (17.5T): the power and the
 * current come from the motor's other numbers, so a change to it alone changes nothing the car does. Shown as the row's own tooltip.
 */
const INFORMATIONAL: Readonly<Record<string, string>> = {
  'class.motor.turns': "Informational only: the motor's power comes from its other numbers",
}

/** The words a text value may take; any other text value (a name, an id) is not edited. */
const CHOICES: Readonly<Record<string, readonly string[]>> = { drive: ['4wd', 'fwd', 'rwd'] }

/** The folders a value goes in: its own place in the table (by path, then by its first word), or the group it sits in. */
function folderTrail(scope: Scope, path: string): string[] {
  const table = scope === 'class' ? CLASS_FOLDERS : TUNING_FOLDERS
  const words = path.split('.')
  const named = table[path] ?? table[words[0]]
  if (scope === 'tuning' && words[0] === 'surface' && words.length > 2) return ['Surface', words[1]]
  if (named !== undefined) return [named]
  return words.length > 1 ? words.slice(0, -1) : ['Other']
}

const PRESET_KEY = 'mrr.dev.tuning-presets'

/**
 * The player's own presets: name → the text of an export. A separate key from every game save; safe to lose. The
 * presets shipped with the game (`SHIPPED_PRESETS`, F-807) are data and are never written here.
 */
const presetStore = {
  all(): Record<string, string> {
    try {
      const parsed: unknown = JSON.parse(localStorage.getItem(PRESET_KEY) ?? '{}')
      if (typeof parsed !== 'object' || parsed === null) return {}
      return Object.fromEntries(Object.entries(parsed).filter((entry): entry is [string, string] => typeof entry[1] === 'string'))
    } catch {
      return {}
    }
  },
  write(presets: Record<string, string>): void {
    localStorage.setItem(PRESET_KEY, JSON.stringify(presets))
  },
}

