const GRAPH_ROWS = 2

// ---------------------------------------------------------------------------------------------------------------
// The panel
// ---------------------------------------------------------------------------------------------------------------

interface Control {
  scope: Scope
  path: string
  binding: BindingApi
}

export class TuningPanel {
  private readonly ws = createWorkspace(shippedTuning, classes)
  /** The shipped content as it was when the panel was made, to prove afterwards that nothing wrote to it. */
  private readonly pristine = JSON.stringify({ tuning: shippedTuning, classes })
  private readonly values = blankTelemetry()
  private readonly root: HTMLElement
  private readonly statusLine: HTMLElement
  private readonly hud: HTMLElement
  private hudTimer: ReturnType<typeof setInterval> | null = null
  private readonly box: HTMLTextAreaElement
  private readonly mount: HTMLElement
  private pane: PaneApi
  /** The top-level folders by key, and whether each was open the last time the panel was rebuilt, so that a rebuild looks the same. */
  private readonly topFolders = new Map<string, FolderApi>()
  private readonly remembered = new Map<string, boolean>()
  private readonly styleSheet: HTMLStyleElement
  private readonly ui = { carClass: 'tc-stock-175' as CarClassId, presetName: 'more-push', preset: '' }
  /** The label of the preset last loaded, until anything is edited, reset or imported. */
  private loaded: string | null = null
  /**
   * The working values are the DRIVING ASSISTANCE car's (F-811): put there because the session's player drives it, with
   * nothing changed since. They are the car's own already, so they are not given to the session and it is not tuned.
   */
  private followsAssistance = false
  private controls: Control[] = []
  private classId: CarClassId = 'tc-stock-175'
  private session: Session | null = null
  private open = false
  private dockLeft = false
  private statusText = ''
  private failure: string | null = null
  private readonly onResize = (): void => this.place()

  constructor(private readonly host: PanelHost) {
    this.styleSheet = document.createElement('style')
    this.styleSheet.textContent = STYLE
    document.head.appendChild(this.styleSheet)

    this.root = document.createElement('div')
    this.root.id = 'mrr-tuning'
    this.root.hidden = true
    this.statusLine = document.createElement('div')
    this.statusLine.className = 'mrr-status'
    this.hud = document.createElement('pre')
    this.hud.className = 'mrr-hud'
    this.hud.dataset.hud = 'telemetry'
    this.mount = document.createElement('div')
    this.box = document.createElement('textarea')
    this.box.placeholder = 'Export puts text here; paste an export here and press Import.'
    this.box.spellcheck = false
    this.box.wrap = 'off'
    this.root.append(this.statusLine, this.hud, this.mount, this.box)
    document.body.appendChild(this.root)
    this.keepKeysOutOfTheGame()

    this.pane = this.build()
    this.pane.disabled = true
    this.drawHud()
    window.addEventListener('resize', this.onResize)
    this.refreshStatus()
  }

  // -- visibility and placement ------------------------------------------------------------------------------

  get isOpen(): boolean {
    return this.open
  }

  setOpen(open: boolean): void {
    this.open = open
    this.root.hidden = !open
    // A disabled pane stops its monitors polling, so a hidden panel costs nothing.
    this.pane.disabled = !open
    if (this.hudTimer !== null) clearInterval(this.hudTimer)
    this.hudTimer = null
    if (open) {
      this.place()
      this.hudTimer = setInterval(() => this.drawHud(), GRAPH_INTERVAL_MS)
    } else this.releaseFocus()
  }

  /** Beside the game when the window has room for it, otherwise on top of the game's edge, on the side the player chose. */
  private place(): void {
    const canvas = document.querySelector('#game canvas')
    const width = this.root.offsetWidth + 16
    let left = this.dockLeft
    if (canvas !== null) {
      const box = canvas.getBoundingClientRect()
      if (window.innerWidth - box.right >= width) left = false
      else if (box.left >= width) left = true
    }
    this.root.classList.toggle('mrr-left', left)
  }

  // -- keys ----------------------------------------------------------------------------------------------------

  /**
   * Typing in the panel must not drive the car, and driving must not be stopped by having clicked the panel. Keys
   * pressed in a text field stay in the panel; clicking anything else gives the keyboard back to the game at once.
   */
  private keepKeysOutOfTheGame(): void {
    const typing = (target: EventTarget | null): boolean =>
      target instanceof HTMLTextAreaElement ||
      target instanceof HTMLSelectElement ||
      (target instanceof HTMLInputElement && !['checkbox', 'button', 'range'].includes(target.type))
    const stop = (event: KeyboardEvent): void => {
      if (typing(event.target)) event.stopPropagation()
    }
    this.root.addEventListener('keydown', (event) => {
      if (!typing(event.target)) return
      event.stopPropagation()
      const field = event.target
      if (field instanceof HTMLElement && (event.key === 'Escape' || (event.key === 'Enter' && !(field instanceof HTMLTextAreaElement)))) {
        setTimeout(() => field.blur(), 0)
      }
    })
    this.root.addEventListener('keyup', stop)
    this.root.addEventListener('keypress', stop)
    this.root.addEventListener('focusin', (event) => {
      if (typing(event.target)) this.host.releaseKeys()
    })
    const giveBack = (): void => {
      setTimeout(() => {
        if (!typing(document.activeElement) && document.activeElement instanceof HTMLElement) document.activeElement.blur()
      }, 0)
    }
    this.root.addEventListener('click', giveBack)
    this.root.addEventListener('change', giveBack)
    // The game cancels the default of a mouse press on its canvas, which is what would move focus out of a field: do it here.
    document.addEventListener('pointerdown', this.leaveOnOutsideClick, true)
  }

  private readonly leaveOnOutsideClick = (event: PointerEvent): void => {
    if (event.target instanceof Node && !this.root.contains(event.target)) this.releaseFocus()
  }

  private releaseFocus(): void {
    if (document.activeElement instanceof HTMLElement && this.root.contains(document.activeElement)) document.activeElement.blur()
  }

  // -- building the controls -----------------------------------------------------------------------------------

  /** Every control, from the working values as they are now. */
  private build(): PaneApi {
    this.controls = []
    this.topFolders.clear()
    const pane = createPane(this.mount)
    this.pane = pane
    this.buildSession()
    this.buildLevers()
    this.buildTelemetry()
    this.buildPresets()
    this.buildClassFolder()
    this.buildTuningFolder()
    this.buildText()
    return pane
  }

  /** Throws the controls away and builds them again, for when what they are bound to changed (another class, a preset saved). */
  private rebuild(): void {
    for (const [key, folder] of this.topFolders) this.remembered.set(key, folder.expanded)
    this.pane.dispose()
    this.mount.replaceChildren()
    this.build().disabled = !this.open
    this.refreshStatus()
  }

  private topFolder(key: string, title: string, expanded: boolean): FolderApi {
    const folder = this.pane.addFolder({ title, expanded: this.remembered.get(key) ?? expanded })
    this.topFolders.set(key, folder)
    return folder
  }

  private buildSession(): void {
    const folder = this.topFolder('session', 'Session', true)
    const options: Record<string, string> = {}
    for (const id of CLASS_ORDER) options[classes[id].name] = id
    folder.addBinding(this.ui, 'carClass', { label: 'class', options }).on('change', (event) => {
      if (typeof event.value === 'string' && event.value !== this.classId) this.host.restart(event.value as CarClassId)
    })
    folder.addButton({ title: 'Reset to class file (restarts, untuned)' }).on('click', () => {
      resetWorkspace(this.ws)
      this.failure = null
      this.loaded = null
      this.afterBulkChange()
      this.host.restart(this.classId)
    })
    folder.addButton({ title: 'Restart session (keeps the values)' }).on('click', () => this.host.restart(this.classId))
    folder.addButton({ title: 'Dock to the other side' }).on('click', () => {
      this.dockLeft = !this.root.classList.contains('mrr-left')
      this.root.classList.toggle('mrr-left', this.dockLeft)
    })
  }

  private buildLevers(): void {
    const folder = this.topFolder('levers', 'Key levers', true)
    for (const lever of KEY_LEVERS) this.addControl(folder, lever.scope, lever.path, lever.note)
  }

  private buildTelemetry(): void {
    const folder = this.topFolder('telemetry', 'Telemetry graphs', true)
    for (const graph of GRAPHS) {
      folder.addBinding(this.values, graph.key, {
        label: graph.label,
        readonly: true,
        view: 'graph',
        min: graph.min,
        max: graph.max,
        rows: GRAPH_ROWS,
        interval: GRAPH_INTERVAL_MS,
        bufferSize: 100,
      })
    }
  }

  /** The readouts as four lines of text at the top of the panel, redrawn at 20 Hz while the panel is open. */
  private drawHud(): void {
    const v = this.values
    const n = (x: number, width: number, digits: number): string => x.toFixed(digits).padStart(width)
    this.hud.textContent = [
      `speed ${n(v.speedMS, 6, 2)} m/s   motor ${n(v.motorRpm, 6, 0)} rpm`,
      `gas   ${n(v.throttle, 6, 2)}       brake ${n(v.brake, 6, 2)}`,
      `steer ${n(v.steerDeg, 6, 1)} deg   yaw ${n(v.yawRateDegS, 7, 1)} deg/s`,
      `lat g ${n(v.lateralG, 6, 2)}       slip F ${n(v.slipFront, 4, 2)}  R ${n(v.slipRear, 4, 2)}`,
    ].join('\n')
  }

  /** The shipped presets first, marked as such, then the player's own; open, so that a new player finds NEWBIE at once. */
  private buildPresets(): void {
    const folder = this.topFolder('presets', 'Presets', true)
    const choices = presetChoices(SHIPPED_PRESETS, presetStore.all())
    if (!choices.some((choice) => choice.key === this.ui.preset)) this.ui.preset = choices[0]?.key ?? ''
    const options: Record<string, string> = {}
    for (const choice of choices) options[choice.label] = choice.key
    folder.addBinding(this.ui, 'preset', { label: 'preset', options }).element.dataset.list = 'presets'
    folder.addButton({ title: 'Load the preset (restarts the session)' }).on('click', () => this.loadPreset())
    folder.addButton({ title: 'Delete the preset (your own only)' }).on('click', () => this.deletePreset())
    folder.addBinding(this.ui, 'presetName', { label: 'name' })
    folder.addButton({ title: 'Save current values under that name' }).on('click', () => this.savePreset())
  }

  private buildClassFolder(): void {
    this.addGroup(this.topFolder('class', `Class: ${this.classId}`, false), 'class')
  }

  private buildTuningFolder(): void {
    this.addGroup(this.topFolder('tuning', 'Tuning (every class)', false), 'tuning')
  }

  private buildText(): void {
    const folder = this.topFolder('text', 'Export and import', true)
    folder.addButton({ title: 'Export what differs (and copy)' }).on('click', () => this.show(toPatchText(this.ws, this.classId), 'Export copied'))
    folder.addButton({ title: 'Copy the diff, old → new' }).on('click', () => {
      this.show(formatDiff(this.classId, workspaceChanges(this.ws, this.classId)), 'Diff copied')
    })
    folder.addButton({ title: 'Class row as code' }).on('click', () => this.show(toCode(this.ws.classes[this.classId]), 'Class row copied'))
    folder.addButton({ title: 'Tuning block as code' }).on('click', () => this.show(toCode(this.ws.tuning), 'Tuning block copied'))
    folder.addButton({ title: 'Import the text below' }).on('click', () => this.importText(this.box.value))
  }

  /** Every value of one object as a control, in folders by the table above. A value added to the data later gets a control with no change here. */
  private addGroup(root: FolderApi, scope: Scope): void {
    const target = scope === 'class' ? this.ws.classes[this.classId] : this.ws.tuning
    const folders = new Map<string, Container>([['', root]])
    for (const path of panelPaths(target)) {
      if (KEY_LEVERS.some((lever) => lever.scope === scope && lever.path === path)) continue
      // A word that is not one of the few choices (an id, a name) has no control, and so must not leave an empty folder behind.
      if (typeof leafAt(target, path) === 'string' && CHOICES[path.slice(path.lastIndexOf('.') + 1)] === undefined) continue
      let parent: Container = root
      let trail = ''
      for (const name of folderTrail(scope, path)) {
        trail = `${trail}/${name}`
        let folder = folders.get(trail)
        if (folder === undefined) {
          folder = parent.addFolder({ title: name, expanded: false })
          folders.set(trail, folder)
        }
        parent = folder
      }
      this.addControl(parent, scope, path, '')
    }
  }

  private addControl(parent: Container, scope: Scope, path: string, note: string): void {
    const target = scope === 'class' ? this.ws.classes[this.classId] : this.ws.tuning
    const value = leafAt(target, path)
    if (value === undefined) return
    const { holder, key } = holderOf(target, path)
    const name = path.slice(path.lastIndexOf('.') + 1)
    const unit = unitOf(path)
    const label = unit === '' ? name : `${name} ${unit}`
    const shipped = leafAt(scope === 'class' ? classes[this.classId] : shippedTuning, path)
    const tip = [`${scope}.${path}`, shipped === undefined ? '' : `shipped: ${String(shipped)}`, note].filter((part) => part !== '').join(' — ')

    let options: BindingOptions
    if (typeof value === 'number') {
      const range = rangeFor(path, value)
      options = { label, min: range.min, max: range.max, step: range.step }
    } else if (typeof value === 'boolean') {
      options = { label }
    } else {
      const choices = CHOICES[name]
      if (choices === undefined) return
      options = { label, options: Object.fromEntries(choices.map((choice) => [choice, choice])) }
    }
    const binding = parent.addBinding(holder, key, options)
    binding.element.dataset.path = `${scope}.${path}`
    const informational = INFORMATIONAL[`${scope}.${path}`]
    // A native `title` cannot be told to show at once or be seen in a screenshot; the informational rows draw their tooltip with CSS (`[data-tip]` below).
    if (informational === undefined) binding.element.title = tip
    else binding.element.dataset.tip = `${informational}\n${tip}`
    binding.on('change', (event) => this.edited(scope, path, event.value, binding))
    this.controls.push({ scope, path, binding })
  }

  // -- editing -------------------------------------------------------------------------------------------------

  private edited(scope: Scope, path: string, value: Leaf, binding: BindingApi): void {
    // A slider's arithmetic leaves float noise (0.30000000000000004); twelve significant figures keep what was typed and drop that.
    if (typeof value === 'number') {
      const clean = Number(value.toPrecision(12))
      if (clean !== value) {
        const { holder, key } = holderOf(scope === 'class' ? this.ws.classes[this.classId] : this.ws.tuning, path)
        holder[key] = clean
        binding.refresh()
      }
    }
    this.failure = null
    this.loaded = null
    this.commit()
  }

  /**
   * After anything that wrote into the working values behind the controls' backs. The controls are built again rather
   * than refreshed: a Tweakpane slider keeps to the steps of the value it was built with, and would move a value that
   * came in from an import or a preset (NEWBIE's 238 W, on the FWD car's 339.97 W slider) onto those steps.
   */
  private afterBulkChange(): void {
    this.rebuild()
    this.commit(false)
  }

  /** The working values changed: mark what differs, and give the running car the new parameters. */
  private commit(apply = true): void {
    // Anything the player does to the values makes them the player's own, no longer the assisted car as it is.
    this.followsAssistance = false
    if (apply) this.applyToSession()
    this.refreshStatus()
  }

  private applyToSession(): void {
    const running = this.host.current()
    if (running === null) return
    const { session } = running
    const id = session.config.carClass
    if (id !== this.classId) return
    const player = session.config.entries.findIndex((entry) => entry.controller === 'human')
    if (player < 0) return
    try {
      setCarParams(session, player, resolveCar(this.ws.classes[id], this.ws.tuning))
      setSurfaceTuning(session, this.ws.tuning.surface)
      setContactTuning(session, this.ws.tuning)
    } catch (error) {
      this.failure = error instanceof Error ? error.message : String(error)
      console.error(`TuningPanel: could not give the car its new parameters: ${this.failure}`)
    }
  }

  private refreshStatus(): void {
    const changes = workspaceChanges(this.ws, this.classId)
    for (const control of this.controls) {
      const target = control.scope === 'class' ? this.ws.classes[this.classId] : this.ws.tuning
      const base = control.scope === 'class' ? classes[this.classId] : shippedTuning
      control.binding.element.classList.toggle('mrr-changed', leafAt(target, control.path) !== leafAt(base, control.path))
    }
    const tuned = this.session !== null && isTunedSession(this.session)
    if (this.failure !== null) this.statusText = `Could not apply: ${this.failure}`
    else if (this.followsAssistance && !tuned) {
      this.statusText = `DRIVING ASSISTANCE: the ${ASSISTANCE_PRESET.name} car, ${changes.length} ${changes.length === 1 ? 'change' : 'changes'} from the shipped ${this.classId}. Change anything and this session is tuned.`
    } else if (changes.length === 0) {
      this.statusText = tuned ? `Shipped values. This session ran with altered values earlier: restart it to clear the mark.` : 'Shipped values. Nothing altered.'
    } else {
      const count = `${changes.length} ${changes.length === 1 ? 'change' : 'changes'}`
      this.statusText =
        this.loaded === null
          ? `TUNED: ${count} from the shipped ${this.classId}. This session is marked tuned.`
          : `TUNED with ${this.loaded}: ${count} from the shipped ${this.classId}. A tuned session sets no records.`
    }
    this.statusLine.textContent = this.statusText
    this.statusLine.classList.toggle('mrr-tuned', changes.length > 0 || tuned)
    this.statusLine.classList.toggle('mrr-error', this.failure !== null)
  }

  // -- text, presets ---------------------------------------------------------------------------------------------

  private show(text: string, done: string): void {
    this.box.value = text
    this.box.scrollTop = 0
    navigator.clipboard.writeText(text).then(
      () => this.say(done),
      () => this.say('Could not use the clipboard; the text is in the box, select it and copy'),
    )
  }

  private say(text: string): void {
    this.statusLine.textContent = text
  }

  /**
   * Reads an export into the working values and gives them to the car: at once, in the session that runs, or, with
   * `restart`, in a fresh session (which a preset's loading asks for). Text for another class restarts in that class.
   * Returns whether the text could be used.
   */
  private importText(text: string, restart = false): boolean {
    try {
      const found = fromPatchText(text, shippedTuning, classes)
      if (found.complete) resetWorkspace(this.ws)
      if (found.tuning !== null) copyLeaves(this.ws.tuning, found.tuning)
      if (found.car !== null) copyLeaves(this.ws.classes[found.car.id], found.car)
      this.failure = null
      this.loaded = null
      const other = found.car !== null && found.car.id !== this.classId ? found.car.id : null
      this.afterBulkChange()
      if (other !== null || restart) this.host.restart(other ?? this.classId)
      else this.applyToSession()
      this.refreshStatus()
      return true
    } catch (error) {
      this.failure = error instanceof Error ? error.message : String(error)
      this.refreshStatus()
      return false
    }
  }

  private savePreset(): void {
    const name = this.ui.presetName.trim()
    if (name === '') return this.say('Give the preset a name first')
    if (isShippedPresetName(SHIPPED_PRESETS, name)) return this.say(`'${name}' is a preset shipped with the game: save your copy under another name`)
    try {
      const presets = presetStore.all()
      presets[name] = toPatchText(this.ws, this.classId)
      presetStore.write(presets)
      this.ui.preset = savedPresetKey(name)
      this.rebuild()
      this.say(`Saved '${name}'`)
    } catch (error) {
      this.say(`Could not save: ${error instanceof Error ? error.message : String(error)}`)
    }
  }

  /** Puts the chosen preset in place and restarts the session with it, which is then tuned, like any session with altered values. */
  private loadPreset(): void {
    const shipped = shippedPresetOf(SHIPPED_PRESETS, this.ui.preset)
    const label = presetChoices(SHIPPED_PRESETS, presetStore.all()).find((choice) => choice.key === this.ui.preset)?.label ?? null
    if (shipped !== null) {
      try {
        applyPreset(this.ws, shipped)
      } catch (error) {
        return this.say(`Could not load '${shipped.name}': ${error instanceof Error ? error.message : String(error)}`)
      }
      this.failure = null
      this.box.value = toPatchText(this.ws, this.classId)
      this.afterBulkChange()
      this.host.restart(this.classId)
    } else {
      const name = savedPresetName(this.ui.preset)
      const text = name === null ? undefined : presetStore.all()[name]
      if (text === undefined) return this.say('That preset is not saved')
      this.box.value = text
      if (!this.importText(text, true)) return
    }
    this.loaded = label
    this.refreshStatus()
  }

  private deletePreset(): void {
    const shipped = shippedPresetOf(SHIPPED_PRESETS, this.ui.preset)
    if (shipped !== null) return this.say(`'${shipped.name}' is shipped with the game and cannot be deleted`)
    const name = savedPresetName(this.ui.preset)
    if (name === null) return
    const presets = presetStore.all()
    delete presets[name]
    try {
      presetStore.write(presets)
    } catch (error) {
      return this.say(`Could not delete: ${error instanceof Error ? error.message : String(error)}`)
    }
    this.rebuild()
  }

  // -- the game's side ---------------------------------------------------------------------------------------------

  /**
   * A new race session has been created (or the panel was opened while one runs): follow its class and give it the
   * working values. `assisted`: the player drives the DRIVING ASSISTANCE car (F-811), and the panel opens on that car —
   * the NEWBIE values, while the player has changed nothing — and gives the session nothing until something is changed.
   * A session without it puts the shipped values back, if all the panel held was the assisted car.
   */
  attach(session: Session | null, assisted = false): void {
    this.session = session
    if (session === null) return
    const id = session.config.carClass
    const otherClass = id !== this.classId
    if (otherClass) {
      this.classId = id
      this.ui.carClass = id
    }
    let refilled = false
    if (assisted && !this.followsAssistance && !workspaceAltered(this.ws)) {
      applyPreset(this.ws, ASSISTANCE_PRESET)
      this.followsAssistance = true
      refilled = true
    } else if (!assisted && this.followsAssistance) {
      resetWorkspace(this.ws)
      this.followsAssistance = false
      refilled = true
    }
    // The controls are bound to the class row on show, and a slider keeps the steps of the value it was built with.
    if (otherClass || refilled) this.rebuild()
    if (!this.followsAssistance && workspaceChanges(this.ws, id).length > 0) this.applyToSession()
    this.refreshStatus()
  }

  /** Once per rendered frame: the player's car into the readouts. The monitors take it from there, twenty times a second. */
  frame(): void {
    if (!this.open) return
    readTelemetry(this.host.current()?.car ?? null, this.values)
  }

  state(): TuningPanelState {
    return {
      open: this.open,
      carClass: this.classId,
      changes: workspaceChanges(this.ws, this.classId),
      shippedIntact: JSON.stringify({ tuning: shippedTuning, classes }) === this.pristine,
      sessionTuned: this.session !== null && isTunedSession(this.session),
      telemetry: { ...this.values },
      status: this.statusText,
      text: this.box.value,
      preset: this.loaded,
      assistance: this.followsAssistance,
    }
  }

  dispose(): void {
    if (this.hudTimer !== null) clearInterval(this.hudTimer)
    window.removeEventListener('resize', this.onResize)
    document.removeEventListener('pointerdown', this.leaveOnOutsideClick, true)
    this.pane.dispose()
    this.root.remove()
    this.styleSheet.remove()
  }
}

/** What the rest of the game (and the debug hook, where there is one) can ask of the panel. */
export interface TuningTools {
  /** Opens or closes the panel; with no argument, toggles it. Does nothing outside a race. */
  open(open?: boolean): void
  /** The panel's state, or null while it has never been opened. */
  state(): TuningPanelState | null
}

/**
 * Puts the tuning panel in the game: `T` opens and closes it while a race scene has a session (except while typing in a
 * field), every new session is given the panel's working values, and the telemetry is fed once per frame. It needs
 * nothing from the debug hook, so the demo build, which has no hook, has the panel.
 */
export function installTuningTools(game: Phaser.Game): TuningTools {
  let panel: TuningPanel | null = null
  const raceScene = (): RaceScene | null => {
    const scene = game.scene.getScene('Race')
    return scene instanceof RaceScene ? scene : null
  }
  const host: PanelHost = {
    current() {
      const race = raceScene()
      const session = race?.session
      const runner = race?.runner
      if (session === null || session === undefined || runner === null || runner === undefined) return null
      const player = Math.max(0, session.config.entries.findIndex((entry) => entry.controller === 'human'))
      return { session, car: runner.curr.cars[player] }
    },
    restart(carClass) {
      for (const key of ['Pause', 'Title', 'Garage']) game.scene.stop(key)
      game.scene.start('Race', { config: { carClass } })
    },
    releaseKeys: () => game.events.emit(Phaser.Core.Events.BLUR),
  }
  const open = (want?: boolean): void => {
    if (raceScene()?.session == null) return
    if (panel === null) {
      panel = new TuningPanel(host)
      panel.attach(raceScene()?.session ?? null, raceScene()?.assisted === true)
    }
    panel.setOpen(want ?? !panel.isOpen)
  }

  window.addEventListener('keydown', (event) => {
    if (event.key.toLowerCase() !== 't' || event.repeat || event.ctrlKey || event.metaKey || event.altKey) return
    const target = event.target
    if (target instanceof HTMLElement && (target.isContentEditable || ['INPUT', 'TEXTAREA', 'SELECT'].includes(target.tagName))) return
    open()
  })

  // Every race session the scene creates is given the working values; the scenes exist once the game is ready.
  const watchRaceScenes = (): void => {
    const race = raceScene()
    if (race === null) throw new Error('The tuning panel: there is no race scene')
    race.events.on(Phaser.Scenes.Events.CREATE, () => panel?.attach(race.session, race.assisted))
  }
  if (raceScene() === null) game.events.once(Phaser.Core.Events.READY, watchRaceScenes)
  else watchRaceScenes()
  game.events.on(Phaser.Core.Events.POST_RENDER, () => panel?.frame())

  return { open, state: () => panel?.state() ?? null }
}
